import { jsx, jsxs } from "react/jsx-runtime";

/**
 * A stand-in for a third-party React component: published JavaScript under
 * `node_modules`, compiled with the production JSX runtime the way libraries
 * ship, so none of its elements carry intervu's source stamp.
 */
export const FixtureWidget = () =>
  jsxs("div", {
    className: "fixture-widget",
    children: [
      jsx("span", { id: "widget-label", children: "Third-party widget" }),
      jsx("button", { id: "widget-button", type: "button", children: "Widget action" }),
    ],
  });
